/* From Uiverse.io by akshat-patel28 - Tags: animation, loader, animated, box */
.__UIV_SCOPE__ .loader {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 30px;
}

.__UIV_SCOPE__ .box-1,.__UIV_SCOPE__ .box-2,.__UIV_SCOPE__ .box-3 {
  width: 1px;
  height: 115px;
  border: 1px solid #e9e9e9;
  background-color: transparent;
  box-sizing: border-box;
}

.__UIV_SCOPE__ .box-1 {
  animation: box1animation 4s  forwards ease-in-out infinite;
}

@keyframes box1animation {
  0% {
    width: 1px;
  }

  12.5% {
    width: 60px;
  }

  25% {
    width: 60px;
  }

  37.5% {
    width: 1px;
  }

  50% {
    width: 1px;
  }

  62.5% {
    width: 1px;
  }

  75% {
    width: 1px;
  }

  100% {
    width: 1px;
  }
}

.__UIV_SCOPE__ .box-2 {
